<script setup lang="tsx">
import { ref, onMounted, computed } from "vue";
import {
  GetJudgeStatusList,
  PostJudgeStatusList,
  GetFriendLinkList,
  PostFriendLinkList,
} from "@/apis/system.ts";
import { GetWebAnnouncement, GetWebNotification, GetWebBanners, PostAnnouncementSave, PostNotificationSave, PostBannerSave } from "@/apis/system.ts";
import { GetSystemImageToken, GetBannerImageToken } from "@/apis/system.ts";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsInfo } from "@/util/tips";
import { HandleR2ImageUpload, CompressImage } from "@/util/md-editor-v3.ts";
import type { UploadImageCallbackUrl } from "@/util/md-editor-v3.ts";
import type { Notification, Announcement, JudgeStatus, FriendLink, BannerItem } from "@/types/system.ts";
import { useBreakpoint } from "@/composables/useBreakpoint";

const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();

// 移动端精简 md-editor-v3 工具栏：隐藏表格、度量、预览主题等次要按钮
const mdEditorToolbarsExclude = computed(() => (isMobile.value
  ? ["github", "save", "pageFullscreen", "fullscreen", "preview", "previewOnly", "catalog", "htmlPreview"]
  : []));

const notification = ref<Notification>({
  theme: "",
  content: "",
});

const announcement = ref<Announcement>({
  title: "",
  content: "",
});

const judgeStatuses = ref<JudgeStatus[]>([]);
const friendLinks = ref<FriendLink[]>([]);

const bannerImages = ref<BannerItem[]>([]);
const bannerSaving = ref(false);
const dragIndex = ref<number | null>(null);
const dragOverIndex = ref<number | null>(null);

const stateLoading = ref(false);
const notificationSaving = ref(false);
const announcementSaving = ref(false);

const judgeStatusSaving = ref(false);
const friendLinkSaving = ref(false);

const statusOptions = [
  { label: "有效", value: "success" },
  { label: "开发中", value: "warning" },
  { label: "失效", value: "default" },
];

const uploadInput = ref<HTMLInputElement | null>(null);

async function handleUploadImg(files: File[], callback: (urls: UploadImageCallbackUrl[]) => void) {
  announcementSaving.value = true;
  await HandleR2ImageUpload(files, callback, globalProperties, GetSystemImageToken);
  announcementSaving.value = false;
}

async function handleBannerFileUpload(files: File[]) {
  if (!files || files.length === 0) return;
  if (bannerSaving.value) return;

  bannerSaving.value = true;

  try {
    const newItems: BannerItem[] = [];
    for (const file of files) {
      const res = await GetBannerImageToken();
      if (res.code !== 0) {
        ShowErrorTips(globalProperties, res.code);
        continue;
      }
      const uploadUrl = res.data.upload_url;
      // 上传前压缩图片
      const imageToUpload = await CompressImage(file);
      await fetch(uploadUrl, {
        method: "PUT",
        headers: { "Content-Type": imageToUpload.type },
        body: imageToUpload,
      });
      newItems.push({ url: res.data.preview_url, link: "" });
    }

    if (newItems.length > 0) {
      const allItems = [...bannerImages.value, ...newItems];
      const saveRes = await PostBannerSave(allItems);
      if (saveRes.code !== 0) {
        ShowErrorTips(globalProperties, saveRes.code);
        return;
      }
      if (saveRes.data && saveRes.data.images) {
        bannerImages.value = saveRes.data.images;
      }
      ShowTextTipsInfo(globalProperties, `已添加 ${newItems.length} 张Banner图片`);
    }
  } catch (e) {
    console.error(e);
    ShowTextTipsError(globalProperties, "上传Banner失败");
  } finally {
    bannerSaving.value = false;
  }
}

const handleRemoveBanner = async (index: number) => {
  if (bannerSaving.value) return;
  bannerSaving.value = true;

  const removed = bannerImages.value[index];
  bannerImages.value.splice(index, 1);

  try {
    const res = await PostBannerSave(bannerImages.value);
    if (res.code !== 0) {
      bannerImages.value.splice(index, 0, removed);
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    if (res.data && res.data.images) {
      bannerImages.value = res.data.images;
    }
    ShowTextTipsInfo(globalProperties, "已删除Banner图片");
  } catch (e) {
    bannerImages.value.splice(index, 0, removed);
    console.error(e);
    ShowTextTipsError(globalProperties, "删除Banner失败");
  } finally {
    bannerSaving.value = false;
  }
};

const handleEditLink = async (index: number) => {
  const current = bannerImages.value[index];
  const newLink = prompt("请输入跳转链接（留空取消链接）：", current.link || "");
  if (newLink === null) return; // 用户取消

  bannerSaving.value = true;
  bannerImages.value[index] = { ...current, link: newLink.trim() };

  try {
    const res = await PostBannerSave(bannerImages.value);
    if (res.code !== 0) {
      bannerImages.value[index] = current; // 回滚
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    if (res.data && res.data.images) {
      bannerImages.value = res.data.images;
    }
    ShowTextTipsInfo(globalProperties, "已更新链接");
  } catch (e) {
    bannerImages.value[index] = current;
    console.error(e);
    ShowTextTipsError(globalProperties, "更新链接失败");
  } finally {
    bannerSaving.value = false;
  }
};

const handleAddBannerByUrl = async () => {
  if (bannerSaving.value) return;

  const url = prompt("请输入Banner图片URL：");
  if (!url || !url.trim()) return;

  bannerSaving.value = true;
  const allItems = [...bannerImages.value, { url: url.trim(), link: "" }];

  try {
    const res = await PostBannerSave(allItems);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    if (res.data && res.data.images) {
      bannerImages.value = res.data.images;
    }
    ShowTextTipsInfo(globalProperties, "已添加Banner图片");
  } catch (e) {
    console.error(e);
    ShowTextTipsError(globalProperties, "添加Banner失败");
  } finally {
    bannerSaving.value = false;
  }
};

const handleFileInputChange = (event: Event) => {
  const target = event.target as HTMLInputElement;
  if (target.files && target.files.length > 0) {
    handleBannerFileUpload(Array.from(target.files));
    target.value = "";
  }
};

// 排序：上移
const handleMoveUp = async (index: number) => {
  if (index === 0 || bannerSaving.value) return;
  bannerSaving.value = true;
  const items = [...bannerImages.value];
  [items[index - 1], items[index]] = [items[index], items[index - 1]];
  try {
    const res = await PostBannerSave(items);
    if (res.code === 0 && res.data?.images) {
      bannerImages.value = res.data.images;
    }
  } catch (e) {
    console.error(e);
  } finally {
    bannerSaving.value = false;
  }
};

// 排序：下移
const handleMoveDown = async (index: number) => {
  if (index >= bannerImages.value.length - 1 || bannerSaving.value) return;
  bannerSaving.value = true;
  const items = [...bannerImages.value];
  [items[index], items[index + 1]] = [items[index + 1], items[index]];
  try {
    const res = await PostBannerSave(items);
    if (res.code === 0 && res.data?.images) {
      bannerImages.value = res.data.images;
    }
  } catch (e) {
    console.error(e);
  } finally {
    bannerSaving.value = false;
  }
};

// 拖拽排序
const handleDragStart = (index: number, event: DragEvent) => {
  if (bannerSaving.value) return;
  dragIndex.value = index;
  if (event.dataTransfer) {
    event.dataTransfer.effectAllowed = "move";
  }
};

const handleDragOver = (index: number, event: DragEvent) => {
  if (dragIndex.value === null) return;
  event.preventDefault();
  event.dataTransfer!.dropEffect = "move";
  dragOverIndex.value = index;
};

const handleDragLeave = () => {
  dragOverIndex.value = null;
};

const handleDrop = async (index: number) => {
  if (dragIndex.value === null || dragIndex.value === index) {
    dragIndex.value = null;
    dragOverIndex.value = null;
    return;
  }
  bannerSaving.value = true;
  const from = dragIndex.value;
  const to = index;
  const items = [...bannerImages.value];
  const [moved] = items.splice(from, 1);
  items.splice(to, 0, moved);

  try {
    const res = await PostBannerSave(items);
    if (res.code === 0 && res.data?.images) {
      bannerImages.value = res.data.images;
    }
  } catch (e) {
    console.error(e);
  } finally {
    dragIndex.value = null;
    dragOverIndex.value = null;
    bannerSaving.value = false;
  }
};

const handleDragEnd = () => {
  dragIndex.value = null;
  dragOverIndex.value = null;
};

const loadWebBanners = async () => {
  try {
    const bannersRes: any = await GetWebBanners();
    const images = bannersRes?.images ?? bannersRes?.data?.images;
    if (images && Object.prototype.toString.call(images) === '[object Array]') {
      bannerImages.value = images.map((item: any) => {
        if (typeof item === "string") {
          // 兼容旧数据：纯字符串 => { url, link: "" }
          return { url: item, link: "" };
        }
        return { url: item.url || "", link: item.link || "" };
      });
    } else {
      bannerImages.value = [];
    }
  } catch (e) {
    console.error("加载banner失败", e);
    bannerImages.value = [];
  }
};

const handleSaveNotification = async () => {
  notificationSaving.value = true;
  try {
    const res = await PostNotificationSave(notification.value.theme, notification.value.content);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsInfo(globalProperties, "保存成功");
  } catch (e) {
    console.error(e);
    ShowErrorTips(globalProperties, "保存失败");
  } finally {
    notificationSaving.value = false;
  }
};

const handleSaveAnnouncement = async () => {
  announcementSaving.value = true;
  try {
    const content = announcement.value.content;
    const res = await PostAnnouncementSave(announcement.value.title, content);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    announcement.value.content = res.data.content;
    ShowTextTipsInfo(globalProperties, "保存成功");
  } catch (e) {
    console.error(e);
    ShowTextTipsError(globalProperties, "保存失败");
  } finally {
    announcementSaving.value = false;
  }
};

// ========== 判官状态管理 ==========

const loadJudgeStatuses = async () => {
  try {
    const res = await GetJudgeStatusList();
    if (res.code === 0 && res.data) {
      judgeStatuses.value = res.data;
    }
  } catch (e) {
    ShowTextTipsError(globalProperties, "加载判官状态失败");
  }
};

const addJudgeStatus = () => {
  judgeStatuses.value.push({ name: "", url: "", status: "success" });
};

const removeJudgeStatus = (index: number) => {
  judgeStatuses.value.splice(index, 1);
};

const moveJudgeStatus = (index: number, direction: -1 | 1) => {
  const target = index + direction;
  if (target < 0 || target >= judgeStatuses.value.length) return;
  const list = judgeStatuses.value;
  [list[index], list[target]] = [list[target], list[index]];
};

const handleSaveJudgeStatuses = async () => {
  // 验证所有项
  for (const item of judgeStatuses.value) {
    if (!item.name.trim() || !item.url.trim()) {
      ShowTextTipsError(globalProperties, "请填写完整的名称和链接");
      return;
    }
  }
  judgeStatusSaving.value = true;
  try {
    const res = await PostJudgeStatusList(judgeStatuses.value);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsInfo(globalProperties, "保存成功");
  } catch (e) {
    console.error(e);
    ShowTextTipsError(globalProperties, "保存失败");
  } finally {
    judgeStatusSaving.value = false;
  }
};

// ========== 友情链接管理 ==========

const loadFriendLinks = async () => {
  try {
    const res = await GetFriendLinkList();
    if (res.code === 0 && res.data) {
      friendLinks.value = res.data;
    }
  } catch (e) {
    ShowTextTipsError(globalProperties, "加载友情链接失败");
  }
};

const addFriendLink = () => {
  friendLinks.value.push({ name: "", url: "" });
};

const removeFriendLink = (index: number) => {
  friendLinks.value.splice(index, 1);
};

const moveFriendLink = (index: number, direction: -1 | 1) => {
  const target = index + direction;
  if (target < 0 || target >= friendLinks.value.length) return;
  const list = friendLinks.value;
  [list[index], list[target]] = [list[target], list[index]];
};

const handleSaveFriendLinks = async () => {
  for (const item of friendLinks.value) {
    if (!item.name.trim() || !item.url.trim()) {
      ShowTextTipsError(globalProperties, "请填写完整的名称和链接");
      return;
    }
  }
  friendLinkSaving.value = true;
  try {
    const res = await PostFriendLinkList(friendLinks.value);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsInfo(globalProperties, "保存成功");
  } catch (e) {
    console.error(e);
    ShowTextTipsError(globalProperties, "保存失败");
  } finally {
    friendLinkSaving.value = false;
  }
};

// ========== 初始化 ==========

const handleReloadStatus = async () => {
  notification.value = await GetWebNotification();
};

const loadWebAnnouncement = async () => {
  try {
    announcement.value = await GetWebAnnouncement();
  } catch (e) {
    ShowTextTipsError(globalProperties, "加载公告失败");
    announcement.value = {
      title: "",
      content: "",
    };
  }
};

onMounted(async () => {
  stateLoading.value = true;
  try {
    await handleReloadStatus();
    await loadWebAnnouncement();
    await loadWebBanners();
    await loadJudgeStatuses();
    await loadFriendLinks();
  } catch (e) {
    ShowTextTipsError(globalProperties, "加载数据失败");
  }
  stateLoading.value = false;
});
</script>

<template>
  <t-loading :loading="stateLoading">
    <t-card class="yj-manage-card" title="站点通知">
      <t-form @submit="handleSaveNotification">
        <t-form-item label="主题">
          <t-select
            v-model="notification.theme"
            :options="[
              { label: 'success', value: 'success' },
              { label: 'info', value: 'info' },
              { label: 'warning', value: 'warning' },
              { label: 'error', value: 'error' },
            ]"
            placeholder="请选择主题"
          />
        </t-form-item>
        <t-form-item label="内容">
          <t-input v-model="notification.content" placeholder="请输入描述" />
        </t-form-item>
        <t-form-item>
          <t-space>
            <t-button theme="primary" type="submit" :loading="notificationSaving">保存</t-button>
          </t-space>
        </t-form-item>
      </t-form>
    </t-card>

    <t-card class="yj-manage-card" title="首页Banner">
      <template #actions>
        <t-space>
          <t-button theme="default" variant="outline" @click="handleAddBannerByUrl" :disabled="bannerSaving">
            添加URL
          </t-button>
          <t-button theme="primary" :loading="bannerSaving" @click="uploadInput?.click()">
            上传图片
          </t-button>
          <input
            ref="uploadInput"
            type="file"
            accept="image/*"
            multiple
            style="display: none"
            @change="handleFileInputChange"
          />
        </t-space>
      </template>

      <t-loading :loading="bannerSaving" :text="'正在保存...'">
        <div v-if="bannerImages.length === 0" class="banner-empty">
          暂无Banner图片，请上传或添加URL
        </div>
        <div v-else class="banner-list">
          <div
            v-for="(item, index) in bannerImages"
            :key="index"
            class="banner-item"
            :class="{
              'banner-dragging': dragIndex === index,
              'banner-dragover': dragOverIndex === index,
            }"
            draggable="true"
            @dragstart="handleDragStart(index, $event)"
            @dragover="handleDragOver(index, $event)"
            @dragleave="handleDragLeave"
            @drop="handleDrop(index)"
            @dragend="handleDragEnd"
          >
            <div class="banner-drag-handle">
              <t-icon name="drag" size="14px" />
            </div>
            <t-image
              :src="item.url"
              fit="cover"
              style="width: 100%; height: 150px; border-radius: 4px;"
            />
            <div class="banner-actions">
              <div class="banner-index">
                <t-button
                  theme="default"
                  variant="text"
                  size="small"
                  :disabled="index === 0 || bannerSaving"
                  @click="handleMoveUp(index)"
                >
                  <t-icon name="arrow-up" size="14px" />
                </t-button>
                <t-button
                  theme="default"
                  variant="text"
                  size="small"
                  :disabled="index >= bannerImages.length - 1 || bannerSaving"
                  @click="handleMoveDown(index)"
                >
                  <t-icon name="arrow-down" size="14px" />
                </t-button>
                <span>#{{ index + 1 }}</span>
              </div>
              <t-space size="small">
                <t-button
                  theme="default"
                  variant="outline"
                  size="small"
                  :disabled="bannerSaving"
                  @click="handleEditLink(index)"
                >
                  {{ item.link ? "编辑链接" : "添加链接" }}
                </t-button>
                <t-button
                  theme="danger"
                  variant="outline"
                  size="small"
                  :disabled="bannerSaving"
                  @click="handleRemoveBanner(index)"
                >
                  删除
                </t-button>
              </t-space>
            </div>
            <div v-if="item.link" class="banner-link-preview">
              <t-icon name="link" size="14px" />
              <span>{{ item.link }}</span>
            </div>
          </div>
        </div>
      </t-loading>
    </t-card>

    <t-card class="yj-manage-card" title="首页公告">
      <template #actions>
        <t-button theme="primary" :loading="announcementSaving" @click="handleSaveAnnouncement">保存</t-button>
      </template>
      <t-form @submit="handleSaveAnnouncement">
        <t-form-item label="标题">
          <t-input v-model="announcement.title" placeholder="请输入描述" />
        </t-form-item>
      </t-form>
      <t-loading :loading="announcementSaving">
        <md-editor-v3
          v-model="announcement.content"
          @save="handleSaveAnnouncement"
          @onUploadImg="handleUploadImg"
          previewTheme="cyanosis"
          :toolbarsExclude="mdEditorToolbarsExclude"
          class="dida-description-editor"
        ></md-editor-v3>
      </t-loading>
    </t-card>

    <!-- 判官状态管理 -->
    <t-card class="yj-manage-card" title="判官状态">
      <template #actions>
        <t-space>
          <t-button variant="outline" @click="addJudgeStatus">添加</t-button>
          <t-button theme="primary" :loading="judgeStatusSaving" @click="handleSaveJudgeStatuses">保存</t-button>
        </t-space>
      </template>
      <div class="config-list">
        <div v-for="(item, index) in judgeStatuses" :key="index" class="config-item">
          <div class="config-item-fields">
            <t-input v-model="item.name" placeholder="名称" class="config-input config-input-name" />
            <t-input v-model="item.url" placeholder="链接 URL" class="config-input config-input-url" />
            <t-select
              v-model="item.status"
              :options="statusOptions"
              placeholder="状态"
              class="config-input config-input-status"
            />
          </div>
          <div class="config-item-actions">
            <t-button
              variant="text"
              size="small"
              :disabled="index === 0"
              @click="moveJudgeStatus(index, -1)"
            >
              上移
            </t-button>
            <t-button
              variant="text"
              size="small"
              :disabled="index === judgeStatuses.length - 1"
              @click="moveJudgeStatus(index, 1)"
            >
              下移
            </t-button>
            <t-button variant="text" theme="danger" size="small" @click="removeJudgeStatus(index)">
              删除
            </t-button>
          </div>
        </div>
        <t-empty v-if="judgeStatuses.length === 0" description="暂无判官状态，请点击添加" />
      </div>
    </t-card>

    <!-- 友情链接管理 -->
    <t-card class="yj-manage-card" title="友情链接">
      <template #actions>
        <t-space>
          <t-button variant="outline" @click="addFriendLink">添加</t-button>
          <t-button theme="primary" :loading="friendLinkSaving" @click="handleSaveFriendLinks">保存</t-button>
        </t-space>
      </template>
      <div class="config-list">
        <div v-for="(item, index) in friendLinks" :key="index" class="config-item">
          <div class="config-item-fields">
            <t-input v-model="item.name" placeholder="名称" class="config-input config-input-name" />
            <t-input v-model="item.url" placeholder="链接 URL" class="config-input config-input-url" />
          </div>
          <div class="config-item-actions">
            <t-button
              variant="text"
              size="small"
              :disabled="index === 0"
              @click="moveFriendLink(index, -1)"
            >
              上移
            </t-button>
            <t-button
              variant="text"
              size="small"
              :disabled="index === friendLinks.length - 1"
              @click="moveFriendLink(index, 1)"
            >
              下移
            </t-button>
            <t-button variant="text" theme="danger" size="small" @click="removeFriendLink(index)">
              删除
            </t-button>
          </div>
        </div>
        <t-empty v-if="friendLinks.length === 0" description="暂无友情链接，请点击添加" />
      </div>
    </t-card>
  </t-loading>
</template>

<style scoped>
.yj-manage-card {
  margin: 20px;
}

.dida-description-editor {
  margin: 10px;
  width: 100%;
}

.banner-empty {
  text-align: center;
  padding: 60px;
  color: #909399;
  font-size: 14px;
}

.banner-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.banner-item {
  position: relative;
  border: 1px solid #e8e8e8;
  border-radius: 6px;
  overflow: hidden;
  transition: box-shadow 0.2s, opacity 0.2s, border-color 0.2s;
}

.banner-item:hover {
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.banner-dragging {
  opacity: 0.5;
}

.banner-dragover {
  border-color: #0052d9;
  box-shadow: 0 0 0 2px rgba(0, 82, 217, 0.2);
}

.banner-drag-handle {
  position: absolute;
  top: 4px;
  right: 4px;
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
